using System;using System.IO;using System.Linq;using System.Collections.Generic;using System.Reflection;using UnityEngine;using UnityEditor;using UnityEngine.SceneManagement;using UnityEditor.SceneManagement;
[InitializeOnLoad]public static class CoastalPineProportions {
const string D="Assets/Scenes/Oasis/CoastalTerrain";static CoastalPineProportions(){EditorApplication.update+=Poll;}static void Poll(){if(EditorApplication.isCompiling||!File.Exists("CoastalPineProportions.request"))return;try{File.Delete("CoastalPineProportions.request");}catch(IOException){return;}Run();}
static void Run(){try{var seen=new HashSet<Mesh>();int cards=0;float worst=1;foreach(string guid in AssetDatabase.FindAssets("t:Prefab",new[]{D+"/Prefabs"})){string path=AssetDatabase.GUIDToAssetPath(guid);if(!Path.GetFileName(path).StartsWith("Pine_")&&!Path.GetFileName(path).StartsWith("Natural Pine"))continue;var prefab=PrefabUtility.LoadPrefabContents(path);foreach(var f in prefab.GetComponentsInChildren<MeshFilter>()){var mesh=f.sharedMesh;if(!seen.Add(mesh)||mesh.name.Contains("Natural proportions v5"))continue;var p=mesh.vertices;var c=mesh.colors;var wind=new List<Vector4>();mesh.GetUVs(1,wind);var minHeight=new Dictionary<Vector2,float>();var maxHeight=new Dictionary<Vector2,float>();for(int i=0;i<p.Length;i++){var key=new Vector2(wind[i].y,wind[i].z);if(!minHeight.ContainsKey(key)){minHeight[key]=p[i].y;maxHeight[key]=p[i].y;}minHeight[key]=Mathf.Min(minHeight[key],p[i].y);maxHeight[key]=Mathf.Max(maxHeight[key],p[i].y);}for(int i=0;i<p.Length;){if(c[i].a<.5f){i++;continue;}if(i+3>=p.Length)break;var center=(p[i]+p[i+1]+p[i+2]+p[i+3])*.25f;var a=(p[i+1]-p[i])*.5f;var b=(p[i+2]-p[i])*.5f;float radius=Mathf.Clamp(Mathf.Sqrt(a.magnitude*b.magnitude),a.magnitude*.7f,a.magnitude*1.1f);var across=a.normalized;var side=(b-across*Vector3.Dot(b,across)).normalized;float seed=center.x*.71f+center.y*1.17f+center.z*.43f;var axis=Vector3.Cross(across,side).normalized;var turn=Quaternion.AngleAxis(Mathf.Sin(seed)*13,axis);across=turn*across;side=turn*side;a=across*radius;b=side*radius;var q=new[]{center-a-b,center+a-b,center-a+b,center+a+b};for(int k=0;k<4;k++){p[i+k]=q[k];var key=new Vector2(wind[i+k].y,wind[i+k].z);wind[i+k]=new Vector4(Mathf.InverseLerp(minHeight[key],maxHeight[key],q[k].y),key.x,key.y,0);}worst=Mathf.Max(worst,a.magnitude/b.magnitude);cards++;i+=4;}mesh.vertices=p;mesh.SetUVs(1,wind);mesh.RecalculateNormals();mesh.RecalculateBounds();var bounds=mesh.bounds;bounds.Expand(1);mesh.bounds=bounds;mesh.name="Natural proportions v5 3D PNG pine";EditorUtility.SetDirty(mesh);}prefab.GetComponent<LODGroup>().RecalculateBounds();PrefabUtility.SaveAsPrefabAsset(prefab,path);PrefabUtility.UnloadPrefabContents(prefab);}AssetDatabase.SaveAssets();var scene=SceneManager.GetSceneByPath("Assets/Editor/DayNightBackups/Gangstar Final Env.unity");EditorSceneManager.MarkSceneDirty(scene);EditorSceneManager.SaveScene(scene);var capture=typeof(FinalPNGCityDetails).GetMethod("Capture",BindingFlags.Static|BindingFlags.NonPublic);capture.Invoke(null,new object[]{scene,new Vector3(813,31,150),new Vector3(819,35,350),"Natural-Proportion-Pines"});File.WriteAllText("FinalEnvironmentRoadReview/PineProportionReport.txt","SUCCESS meshes="+seen.Count+" local needle cards corrected="+cards+"; square PNG mapped to equal-axis orthogonal foliage cards, max aspect="+worst+"; varied local leaf angles; trunk heights retained; same geometry count; wind weights corrected; prefab LOD bounds updated.");}catch(Exception e){File.WriteAllText("FinalEnvironmentRoadReview/PineProportionReport.txt","FAILED "+e);Debug.LogException(e);}}
}
